        "2GB / 100Mbps → 理论约 172 秒、按 85% 效率约 202 秒（3 分 22 秒）；100M 宽带理论最大 12.5 MB/s；1GB 按 60% 压缩 → 剩 409.6MB、省 614.4MB；300M 宽带、延迟 90ms → 给出本地/路由/远端判断与优化要点。",
