        "8 km / 22 分钟 / 起步 12 元 / 里程 2.6 元 → 出租 ¥32.80；快车 32.80、专车 47.28、顺风车 21.32；每月 22 天往返 → 打车 ¥1443 vs 地铁 ¥264。",
