        ['日均用水量', '滤芯额定净水量', '上次更换日期', '每周洗衣次数', '使用年限', '上次清洁天数', '空调台数', '上次清洗月数', '购买价格', '成色'],
        "6 个计算器同页：滤芯更换 + 洗衣机筒清洁 + 空调清洗 + 以旧换新 + 家电寿命 + 家电耗电与电费，hash 直链可直达",
        "日均 15L、额定 4 吨 → 剩余 267 天、下次 2027-07-23、年耗材约 164 元；每周洗 6 次 / 5 年 / 90 天未清 → 建议间隔 16 天；3 台空调 6 年未洗 → 本次 420 元、年度预算 840 元（每 6 个月一次）；4200 元用 9 年 → 残值约 210 元、可抵扣 189~231 元。",
