        "剪发 45 元、每年 8 次、洗吹 0 元 → 年花费 360 元、约每 6.5 周一次；染发 300 元、每年 2 次、护理 50 元/月 → 年成本 1200 元、单次均摊 600 元；500ml、每次 8ml、每周 5 次 → 约 12.5 周用完、年用量约 2.08 升。",
