        ['原票价', '距发车小时', '发车时间', '安检排队', '步行到检票口', '建议提前量', '重量', '长', '宽', '高'],
        "3 个铁路出行工具同页：改签费 + 进站时间 + 行李规格，hash 直链可直达",
