        "步行 200m、等候 3 分钟、1 次换乘 → 单次约 5.4 分钟；单程 4 元、每月 44 次、月票 100 元 → 不办 176 元、办票省 76 元；末班 22:30、当前 22:00、步行 8 分钟 → 赶得上，剩余 22 分钟。",
